export type ParsedWithdrawInstruction<
  TProgram extends string = typeof ZK_POOL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Caller. Pays for the NullifierRecord PDA creation. */
    payer: TAccountMetas[0];
    /** Pool state PDA. Seeds: `[POOL_SEED]`. */
    pool: TAccountMetas[1];
    /**
     * Nullifier record PDA.
     *
     * Seeds: `[NULLIFIER_RECORD_SEED, pool, nullifier_hash]`.
     * `init` fails if the account already exists — double-spend protection.
     */
    nullifierRecord: TAccountMetas[2];
    /** SOL vault PDA. Seeds: `[VAULT_SEED, pool]`. */
    vault: TAccountMetas[3];
    /**
     * Recipient of the withdrawn SOL.
     * Must match the `recipient` public input.
     */
    to: TAccountMetas[4];
    /** Verifier program (deployed in stage 3.4). */
    verifierProgram: TAccountMetas[5];
    /** Solana system program. */
    systemProgram: TAccountMetas[6];
  };
  data: WithdrawInstructionData;
};

export function parseWithdrawInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedWithdrawInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      pool: getNextAccount(),
      nullifierRecord: getNextAccount(),
      vault: getNextAccount(),
      to: getNextAccount(),
      verifierProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getWithdrawInstructionDataDecoder().decode(instruction.data),
  };
}
